REPORT_TEMP = Path("reports/RC1_FIREBASE_INSTALLER_TEMP.md")


class InstallError(RuntimeError):
    pass


def run(
    command: list[str],
    *,
    check: bool = True,
    clean_auth: bool = False,
    timeout: int | None = None,
    live: bool = False,
) -> subprocess.CompletedProcess[str]:
    env = os.environ.copy()
    if clean_auth:
        env.pop("GH_TOKEN", None)
        env.pop("GITHUB_TOKEN", None)
        env["GIT_TERMINAL_PROMPT"] = "0"

    if live:
        result = subprocess.run(
            command,
            text=True,
            check=False,
            env=env,
            timeout=timeout,
        )
    else:
        result = subprocess.run(
            command,
            text=True,
            capture_output=True,
            check=False,
            env=env,
            timeout=timeout,
        )

    if check and result.returncode != 0:
        detail = ""
        if not live:
            detail = (result.stderr or result.stdout or "").strip()
        raise InstallError(
            f"Komut başarısız: {' '.join(command)}"
            + (f"\n{detail}" if detail else "")
        )

    return result


def sha256(path: Path) -> str:
    digest = hashlib.sha256()
    with path.open("rb") as handle:
        for chunk in iter(lambda: handle.read(1024 * 1024), b""):
            digest.update(chunk)
    return digest.hexdigest()


def decode(value: str) -> str:
    return base64.b64decode(value).decode("utf-8")


def target_paths() -> list[Path]:
    return sorted(
        {Path(path) for path in PATCHES} |
        {Path(path) for path in WRITES},
        key=str,
    )


def verify_repository() -> None:
    required = [
        Path(".git"),
        Path("pubspec.yaml"),
        Path("lib/main.dart"),
        Path("lib/main_navigation.dart"),
        Path(".github/workflows/android-apk.yml"),
        QUESTIONS,
    ]

    missing = [str(path) for path in required if not path.exists()]
    if missing:
        raise InstallError(
            "Kurulum BilgiRotasi depo kökünde çalıştırılmalı. "
            "Eksik: " + ", ".join(missing)
        )

    branch = run(["git", "branch", "--show-current"]).stdout.strip()
    if branch != "main":
        raise InstallError(
            f"Kurulum main dalında çalıştırılmalı. Geçerli dal: {branch or '?'}"
        )

    pubspec = Path("pubspec.yaml").read_text(encoding="utf-8")
    if f"version: {EXPECTED_VERSION}" not in pubspec:
        raise InstallError(
            f"Beklenen temel sürüm {EXPECTED_VERSION} bulunamadı. "
            "Önce git pull --ff-only çalıştırın."
        )

    for path in target_paths():
        if not path.exists():
            continue

        unstaged = run(
            ["git", "diff", "--quiet", "--", str(path)],
            check=False,
        )
        staged = run(
            ["git", "diff", "--cached", "--quiet", "--", str(path)],
            check=False,
        )

        if unstaged.returncode != 0 or staged.returncode != 0:
            raise InstallError(
                f"Hedef dosyada önceden yerel değişiklik var: {path}"
            )

    print("GitHub ile eşitlik kontrol ediliyor...")
    run(
        ["git", "fetch", "origin", "main"],
        clean_auth=True,
        timeout=120,
        live=True,
    )

    local = run(["git", "rev-parse", "HEAD"]).stdout.strip()
    remote = run(["git", "rev-parse", "origin/main"]).stdout.strip()

    if local != remote:
        raise InstallError(
            "Codespaces main dalı GitHub ile aynı değil. "
            "Önce git pull --ff-only çalıştırın."
        )


def preflight_patches() -> None:
    """Simulate every patch in real execution order without writing files."""
    errors: list[str] = []

    for raw_path, items in PATCHES.items():
        path = Path(raw_path)
        if not path.exists():
            errors.append(f"Yama hedefi bulunamadı: {path}")
            continue

        simulated = path.read_text(encoding="utf-8")

        for index, item in enumerate(items, start=1):
            old = decode(item["old"])
            new = decode(item["new"])
            expected = int(item["count"])
            actual = simulated.count(old)

            if actual != expected:
                preview = old.replace("\n", "\\n")[:140]
                errors.append(
                    f"{path} • yama {index}: {preview!r} "
                    f"eşleşmesi {actual}, beklenen {expected}"
                )
                break

            simulated = simulated.replace(old, new)

    if errors:
        raise InstallError(
            "Ön kontrol başarısız:\n- " + "\n- ".join(errors)
        )

def apply_changes() -> None:
    for raw_path, items in PATCHES.items():
        path = Path(raw_path)
        if not path.exists():
            raise InstallError(f"Yama hedefi bulunamadı: {path}")

        text = path.read_text(encoding="utf-8")

        for item in items:
            old = decode(item["old"])
            new = decode(item["new"])
            expected = int(item["count"])
            actual = text.count(old)

            if actual != expected:
                raise InstallError(
                    f"{path} içinde beklenen bölüm bulunamadı. "
                    f"Eşleşme: {actual}, beklenen: {expected}"
                )

            text = text.replace(old, new)

        path.write_text(text, encoding="utf-8")

    for raw_path, payload in WRITES.items():
        path = Path(raw_path)
        path.parent.mkdir(parents=True, exist_ok=True)
        path.write_text(decode(payload), encoding="utf-8")


def validate_firebase_config() -> None:
    config = json.loads(
        Path("firebase/google-services.json").read_text(
            encoding="utf-8",
        )
    )

    client = config["client"][0]
    package_name = client["client_info"][
        "android_client_info"
    ]["package_name"]

    if package_name != "com.leventua.bilgirotasi":
        raise InstallError("Firebase paket adı uyuşmuyor.")

    oauth_clients = client.get("oauth_client", [])
    if not any(
        item.get("client_type") == 1
        for item in oauth_clients
    ):
        raise InstallError(
            "Android Google OAuth istemcisi bulunamadı."
        )

    if not any(
        item.get("client_type") == 3
        for item in oauth_clients
    ):
        raise InstallError(
            "Web Google OAuth istemcisi bulunamadı."
        )


def run_quality_checks(question_hash: str) -> None:
    if sha256(QUESTIONS) != question_hash:
        raise InstallError(
            "assets/questions.json değişti; işlem durduruldu."
        )

    validate_firebase_config()
    run(["git", "diff", "--check"])

    try:
        result = run(
            [
                "python3",
                "tools/rc1_quality_gate.py",
                "--report",
                str(REPORT_TEMP),
            ]
        )
        print(result.stdout)
    finally:
        REPORT_TEMP.unlink(missing_ok=True)

    dart_files = [
        "lib/main.dart",
        "lib/main_navigation.dart",
        "lib/app_build_info.dart",
        "lib/account_cloud.dart",
        "test/rc1_quality_gate_test.dart",
        "test/account_cloud_policy_test.dart",
    ]

    if shutil.which("dart"):
        print("Dart biçimlendirme çalışıyor...")
        run(["dart", "format", *dart_files], live=True)
    else:
        print(
            "ℹ Dart Codespaces içinde yok; "
            "biçim kontrolü GitHub Actions'ta çalışacak."
        )

    lock_path = Path("pubspec.lock")
    lock_existed = lock_path.exists()
    lock_backup = lock_path.read_bytes() if lock_existed else None

    try:
        if shutil.which("flutter"):
            print("Flutter analiz ve testleri çalışıyor...")
            run(["flutter", "pub", "get"], live=True)
            run(
                [
                    "flutter",
                    "analyze",
                    "--no-fatal-warnings",
                    "--no-fatal-infos",
                ],
                live=True,
            )
            run(["flutter", "test"], live=True)
        else:
            print(
                "ℹ Flutter Codespaces içinde yok; "
                "analiz, test ve Android derlemesi "
                "GitHub Actions'ta çalışacak."
            )
    finally:
        if lock_existed and lock_backup is not None:
            lock_path.write_bytes(lock_backup)
        elif not lock_existed:
            lock_path.unlink(missing_ok=True)

    if sha256(QUESTIONS) != question_hash:
        raise InstallError(
            "Kontrollerden sonra soru dosyası değişti."
        )


def commit_and_push() -> None:
    allowed = {str(path) for path in target_paths()}

    run(["git", "add", "--", *sorted(allowed)])

    staged = set(
        run(
            ["git", "diff", "--cached", "--name-only"]
        ).stdout.splitlines()
    )

    if staged != allowed:
        unexpected = staged - allowed
        missing = allowed - staged
        details = []
        if unexpected:
            details.append(
                "beklenmeyen: " + ", ".join(sorted(unexpected))
            )
        if missing:
            details.append(
                "eksik: " + ", ".join(sorted(missing))
            )
        raise InstallError(
            "Commit dosyaları doğrulanamadı ("
            + "; ".join(details)
            + ")"
        )

    print("Commit oluşturuluyor...")
    run(
        [
            "git",
            "-c",
            "commit.gpgsign=false",
            "commit",
            "-m",
            COMMIT_MESSAGE,
        ],
        live=True,
        timeout=120,
    )

    print("GitHub'a gönderiliyor...")
    run(
        ["git", "push", "origin", "main"],
        clean_auth=True,
        live=True,
        timeout=180,
    )


def restore(
    backups: dict[Path, bytes | None],
) -> None:
    run(["git", "reset"], check=False)

    for path, content in backups.items():
        try:
            if content is None:
                path.unlink(missing_ok=True)
            else:
                path.parent.mkdir(parents=True, exist_ok=True)
                path.write_bytes(content)
        except Exception:
            pass

    REPORT_TEMP.unlink(missing_ok=True)


def main() -> int:
    print("Bilgi Rotası — Google Girişi ve Bulut Kayıt V2")
    print("=" * 66)
    print(f"Temel sürüm: {EXPECTED_VERSION}")
    print(f"Yeni sürüm : {NEW_VERSION} • RC2")
    print()

    verify_repository()

    question_hash = sha256(QUESTIONS)
    backups = {
        path: path.read_bytes() if path.exists() else None
        for path in target_paths()
    }

    try:
        print("Tüm dosya eşleşmeleri önceden doğrulanıyor...")
        preflight_patches()
        print("✓ Ön kontrol ve gerçek uygulama sırası doğrulandı.")

        print("Dosyalar güvenli biçimde güncelleniyor...")
        apply_changes()

        print("Firebase yapılandırması doğrulanıyor...")
        run_quality_checks(question_hash)

        print("✓ Google giriş altyapısı hazır.")
        print("✓ Firestore bulut kaydı hazır.")
        print("✓ Misafir kullanıcıda Günlük Görev gizlendi.")
        print("✓ Misafir ve Google kayıtları ayrıldı.")
        print("✓ Soru dosyasına dokunulmadı.")

        commit_and_push()
    except Exception:
        restore(backups)
        raise

    print()
    print("KURULUM BAŞARILI")
    print("=" * 66)
    print("Sürüm   : 1.47.0+62 • RC2")
    print("Artifact: BilgiRotasi-Signed-RC2-1.47.0-62")
    print("APK     : BilgiRotasi-1.47.0-62-signed.apk")
    print()
    print(
        "GitHub Actions yeşil olduktan sonra APK mevcut "
        "uygulamanın üzerine kurulmalıdır."
    )
    return 0


if __name__ == "__main__":
    try:
        raise SystemExit(main())
    except subprocess.TimeoutExpired as error:
        print()
        print("KURULUM DURDURULDU")
        print("=" * 66)
        print(
            "Komut zaman aşımına uğradı: "
            + " ".join(error.cmd)
        )
        raise SystemExit(1)
    except InstallError as error:
        print()
        print("KURULUM DURDURULDU")
        print("=" * 66)
        print(error)
        raise SystemExit(1)
    except KeyboardInterrupt:
        print("\nKurulum kullanıcı tarafından durduruldu.")
        raise SystemExit(130)
